const app=$('#app'),modal=$('#modal');
function updateConnection(){const b=$('#connection-state');if(b){b.textContent=navigator.onLine?'':'Offline · local work is still available';b.hidden=navigator.onLine}}
window.addEventListener('offline',updateConnection);window.addEventListener('online',()=>{updateConnection();if(libraryReady)checkSharing()});
let renderedView=null;
function notify(message){clearTimeout(noticeTimer);$('#notice').textContent=message;$('#notice').style.display='block';noticeTimer=setTimeout(()=>$('#notice').style.display='none',7000)}
function error(e){console.error(e);const box=$('#error');if(box){box.textContent=e.message||String(e);box.scrollIntoView({block:'nearest'})}else notify(e.message||String(e))}
async function checkSharing(){if(healthChecking)return;healthChecking=true;const retry=$('[data-action=check-sharing]');if(retry)retry.disabled=true;const status=$('#sharing-status');if(status)status.textContent='Checking sharing connection…';try{const result=await retryTransfer(()=>api('health'));health=!!result.configured;sharingIssue=health?'':'Online sharing is unavailable. Local editing and downloads still work.'}catch(e){health=false;sharingIssue=e.code==='STORAGE_ACCESS_UNAVAILABLE'?e.message:'Sharing connection failed. Your local copy is safe; retry when connected.'}finally{healthChecked=true;healthChecking=false;const banner=$('#service-status');if(banner){banner.textContent=sharingIssue;banner.hidden=health}const publish=$('[data-action=publish]');if(publish)publish.disabled=!health||!selected?.blob||!!sharingProblem(selected);const message=$('#sharing-status');if(message)message.textContent=health?'':sharingIssue;const button=$('[data-action=check-sharing]');if(button){button.hidden=health;button.disabled=false}}}
async function api(op,data,id){const signal=uploadController?AbortSignal.any([uploadController.signal,AbortSignal.timeout(65000)]):AbortSignal.timeout(65000);const r=await fetch('/api/clip?op='+op+(id?'&id='+encodeURIComponent(id):''),data?{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(data),signal}:{signal});let v;try{v=await r.json()}catch(e){if(e.name==='AbortError')throw e;throw Error('The sharing service did not respond. Your local copy is safe.')}if(!r.ok)throw Object.assign(Error(v.error||'Sharing failed. Keep your local copy and retry.'),{status:r.status,code:v.code});return v}
function shell(content,page='My recordings',view=page){discussionUI?.destroy();discussionUI=null;const navigated=renderedView!==view;renderedView=view;markupUI?.destroy();markupUI=null;app.innerHTML=`<div class="shell"><aside class="sidebar">${brand()}<div class="nav-label">YOUR SPACE</div><nav class="nav" aria-label="Main navigation"><button class="${page==='My recordings'?'active':''}" data-action="home" ${page==='My recordings'?'aria-current="page"':''}>${icon('grid')}My recordings</button><button class="${page==='Privacy'?'active':''}" data-action="privacy" ${page==='Privacy'?'aria-current="page"':''}>${icon('shield')}Privacy & sharing</button><button class="${page==='Help'?'active':''}" data-action="help" ${page==='Help'?'aria-current="page"':''}>${icon('shield')}Help & settings</button></nav><div class="side-note"><strong>Show what you mean.</strong>A quick walkthrough.<br>A thoughtful reply.<br>One less meeting.<p class="small" style="margin-top:24px;margin-bottom:0">Local until you publish.<br>No viewer seats.</p></div></aside><div class="workspace"><header class="topbar"><span class="breadcrumb small muted">Your space <span aria-hidden="true">/</span> ${page}</span>${brand()}<div class="top-actions"><span class="tag">Early access · local first</span><button class="icon-button" data-action="theme" aria-label="Toggle light or dark mode">${icon('moon')}</button><button class="icon-button" data-action="help" aria-label="Help and recording guidance">${icon('shield')}</button></div></header><main class="content" id="main" tabindex="-1"><p id="connection-state" class="notice" role="status" ${navigator.onLine?'hidden':''}>${navigator.onLine?'':'Offline · local work is still available'}</p><div id="error" class="error-box" role="alert"></div><div id="service-status" class="notice" role="status" ${healthChecked&&!health?'':'hidden'}>${esc(sharingIssue)}</div>${emergencyBlob?`<section class="notice" role="alert"><strong>One recording still needs a download.</strong><p>It could not be saved to this browser. Download it and check your file before closing this tab.</p><div class="actions"><a class="btn primary" href="${emergencyURL}" download="screennote-recovered.${emergencyBlob.type.startsWith('video/mp4')?'mp4':'webm'}">Download captured recording</a><button class="btn" data-action="acknowledge-recovery">I saved my copy</button></div></section>`:''}${content}<footer class="footer"><span>ScreenNote · A little more human.</span><span>Your recordings stay here until you choose to publish. <button class="btn" data-action="privacy">Privacy & limits</button></span></footer></main></div></div>`;if(navigated){window.scrollTo({top:0,left:0,behavior:'instant'});$('#main').focus({preventScroll:true})}}
const isShared=c=>!!c.shared&&!c.revoked&&c.expiresAt>Date.now();
function unsavedTitle(){const field=$('#recording-title-input');return !!(selected&&field&&field.value!==(isGeneratedTitle(selected.title)?'Untitled recording':selected.title))}
function confirmEditorLeave(){return !unsavedTitle()||confirm('Leave this recording? Your unsaved title will be lost. Your saved video stays on this device.')}
