 const returning=clips.length>0;
 shell(`<div class="heading library-heading"><div><div class="eyebrow">YOUR WORK. CLEARLY EXPLAINED.</div><h1>${returning?'Your recordings.':'Show it. Send it. Sorted.'}</h1><p>${returning?'Pick up a conversation, or start a new one.':'Record a walkthrough. Share a link. Get useful feedback.'}</p></div><div class="actions"><button class="btn primary" data-action="new-recording">${icon('plus')}${canRecord||window.__ANDROID_APP__?'New recording':'Add a video'}</button><label class="btn" for="import-video">${icon('download')}Import video</label></div></div>
 <div class="workspace-summary"><span class="status-dot"></span>Local until you publish <span>·</span> No account needed to watch <button class="text-button" data-action="help">Limits & help</button></div>
 ${returning?libraryMarkup():''}
 <details class="record-setup" id="record-setup" ${returning?'':'open'}><summary>${canRecord||window.__ANDROID_APP__?'Record something new':'Import a device recording'}</summary><section class="record-grid compact-recorder"><div class="panel record-options ${canRecord?'':'import-only'}"><div class="recorder-intro"><div><div class="eyebrow">A LITTLE CONTEXT GOES A LONG WAY</div><h2>${canRecord?'Ready to record?':'Bring your recording.'}</h2><p>${canRecord?'Choose your screen next. Review before you share.':'Use your phone’s screen recorder, then import the video here.'}</p></div>${icon('screen')}</div>
 <button class="btn primary" data-action="record" ${canRecord&&!emergencyBlob?'':'disabled'}>${icon('video')}${canRecord?'Start recording':window.__ANDROID_APP__?'Import a recording':'Screen capture unavailable'} ${icon('arrow')}</button>
 ${!canRecord?'<p class="small">'+(window.__ANDROID_APP__?'Use Record screen below to capture, then bring the recording in here.':'This browser does not offer screen capture. MP4 and WebM imports work here.')+'</p>':''}
 <div class="record-defaults">${option('mic','Microphone','Include your voice','mic',canRecord)}<div class="field"><label for="record-quality">Recording quality</label><select id="record-quality" ${canRecord?'':'disabled'}><option value="saver">Data saver · smaller files</option><option value="balanced" selected>Balanced · everyday walkthroughs</option><option value="clear">Clear text · larger files</option></select></div></div>
 <details class="advanced-recording"><summary>Camera, audio & microphone source</summary>${option('video','Camera bubble','Move and resize it in the preview','camera',canRecord)}${option('sound','Shared-screen audio','When your browser offers it','system',canRecord)}<div class="field"><label for="mic-source">Microphone source</label><select id="mic-source" ${canRecord?'':'disabled'}><option value="">Browser default</option></select><button class="btn" data-action="list-mics" ${canRecord?'':'disabled'}>List microphones</button></div></details>
 <p class="record-limits">Local: 30 min / 250 MB · Share: 10 min / 50 MB</p><input class="file-input visually-hidden" id="import-video" type="file" accept="video/webm,video/mp4" aria-label="Import an MP4 or WebM video"><p id="import-status" role="status"></p></div>
 <aside class="record-guide"><span class="guide-icon">${icon('play')}</span><h2>Less back-and-forth.</h2><ol><li><strong>Show the detail.</strong> Screen, voice, optional camera.</li><li><strong>Make it clear.</strong> Trim, annotate or add context.</li><li><strong>Keep the conversation moving.</strong> Share, reply and resolve.</li></ol><button class="btn" data-action="sample">${icon('play')}Explore a sample walkthrough</button></aside></section></details>
 ${returning?'':libraryMarkup()}`);
 $('#import-video').onchange=e=>{const file=e.target.files[0];if(file)run(async()=>{const status=$('#import-status');status.textContent='Checking your video…';e.target.disabled=true;try{await importVideo(file)}finally{e.target.value='';e.target.disabled=false;if(status.isConnected)status.textContent=''}})};
 for(const name of ['library-search','library-status','library-sort'])$('#'+name).addEventListener(name==='library-search'?'input':'change',renderLibrary);
 renderLibrary();
