function libraryMarkup(){return `<section class="library-section" aria-label="Your recordings"><div class="section-head"><h2>Your library <span class="muted small">${clips.length}</span></h2><span class="small muted">On this device</span></div><div class="library-filters"><div class="field"><label for="library-search">Find a recording</label><input id="library-search" type="search" placeholder="Search titles" value="${esc(libraryFilters.query)}"></div><div class="field"><label for="library-status">Show</label><select id="library-status">${[['all','All recordings'],['local','Local'],['shared','Shared'],['needs-feedback','Needs feedback'],['changes-requested','Changes requested'],['approved','Approved']].map(([v,t])=>`<option value="${v}" ${libraryFilters.status===v?'selected':''}>${t}</option>`).join('')}</select></div><div class="field"><label for="library-sort">Sort</label><select id="library-sort">${[['newest','Newest first'],['oldest','Oldest first'],['title','Title A–Z']].map(([v,t])=>`<option value="${v}" ${libraryFilters.sort===v?'selected':''}>${t}</option>`).join('')}</select></div></div><p id="library-count" class="small muted" role="status"></p><div class="clip-grid" id="library-grid"></div></section>`}
function renderLibrary(){
 libraryFilters={query:$('#library-search').value,status:$('#library-status').value,sort:$('#library-sort').value};
 const visible=filterRecordings(clips,libraryFilters);$('#library-count').textContent=clips.length?`${visible.length} of ${clips.length} recordings`:'';
 $('#library-grid').innerHTML=visible.length?visible.map(c=>`<article class="clip-card"><button class="clip-art" data-open="${c.id}" aria-label="Open ${esc(c.title)}">${c.thumbnail?`<img src="${c.thumbnail}" alt="" loading="lazy">`:icon('video')}<span class="card-play">${icon('play')}</span><span class="duration">${formatTime(c.duration)}</span></button><div class="clip-body"><div class="card-badges"><span class="clip-badge ${isShared(c)?'shared':''}">${isShared(c)?'Shared':'Local'}</span><span class="review-badge" data-review="${esc(c.reviewStatus||'needs-feedback')}">${reviewLabel(c.reviewStatus)}</span></div><h3>${esc(isGeneratedTitle(c.title)?'Untitled recording':c.title)}</h3><div class="clip-status">${c.cloudDeleted?'Upload deleted':isShared(c)?'Link expires '+new Date(c.expiresAt).toLocaleDateString():c.revoked?'Sharing stopped':c.shared?'Link expired':c.managementOnly?'Management access only':c.sample?'Sample walkthrough':'Saved on this device'} · ${new Date(c.createdAt).toLocaleDateString()}</div><div class="card-actions"><button class="btn" data-open="${c.id}">Open recording ${icon('arrow')}</button><button class="icon-button" data-rename="${c.id}" aria-label="Rename ${esc(c.title)}">✎</button></div></div></article>`).join(''):`<div class="empty"><h3>${clips.length?'No matching recordings.':'Your first clear explanation starts here.'}</h3><p>${clips.length?'Try another title or filter.':'Record a message or explore a sample walkthrough.'}</p>${clips.length?'<button class="btn" data-action="clear-filters">Clear filters</button>':'<button class="btn" data-action="sample">Try a sample clip</button>'}</div>`;
}
