function fitPlayer(video){if(!video)return;const fit=()=>{if(video.videoWidth&&video.videoHeight){video.style.aspectRatio=video.videoWidth+'/'+video.videoHeight;video.parentElement.style.setProperty('--media-ratio',video.videoWidth/video.videoHeight)}};video.addEventListener('loadedmetadata',fit);video.addEventListener('resize',fit);fit()}
function localVideo(){resetURL();if(!selected.blob)return '<div class="notice">Management access restored. The video file is not stored on this device. Use the shared viewer while the link is active.</div>';objectURL=URL.createObjectURL(selected.blob);return `<video id="player" src="${objectURL}" controls playsinline preload="metadata" aria-label="Recording preview"></video>`}
function editor(c){selected=c;const shareLocked=c.uploadAttempted&&!newShareIdentity(c),shared=isShared(c),cloud=!!(c.shared||c.revoked||c.uploadAttempted)&&!c.cloudDeleted&&!c.cloudMissing;shell(`<div class="heading editor-heading"><div><h1 class="recording-title">Review & share</h1><p>${c.blob?'Saved on this device. Review your video before sharing.':'Manage your shared video.'}</p></div><button class="btn" data-action="home">${icon('back')}My recordings</button></div><div class="title-field field"><label for="recording-title-input">Video title</label><div class="title-controls"><input id="recording-title-input" maxlength="100" required value="${esc(isGeneratedTitle(c.title)?'Untitled recording':c.title)}"><button class="btn" data-action="save-title">Save title</button></div><p id="title-status" class="small" role="status"></p></div><div class="editor-grid"><section class="editor-preview"><div class="video-panel">${localVideo()}</div><div class="editor-actions"><button class="btn" data-action="download" ${c.blob?'':'disabled'}>${icon('download')}Download video</button><button class="btn" data-action="bug-report">Add bug report</button><details class="local-options"><summary>More actions</summary>${c.originalFilename?`<details class="source-filename"><summary>Original filename</summary><span>${esc(c.originalFilename)}</span></details>`:''}<button class="btn danger" data-action="remove-local">${c.blob?'Remove local copy':'Remove recovery access'}</button></details></div></section><aside><section class="panel"><div class="eyebrow">${shared?'OUT IN THE WORLD':c.blob?'READY TO SEND?':'SHARING INACTIVE'}</div><h2>${shared?'One link. All the context.':c.blob?'Share your video':'Manage your uploaded video.'}</h2><p>${c.blob?'Share an unlisted link. Anyone with the link can watch and reply unless you add a password.':'Use your recovered keys to manage this upload. The recovery file does not include the video.'}</p>${shared?`<a class="share-link" href="/v/${c.id}" target="_blank" rel="noopener">${location.origin}/v/${c.id}</a><div class="actions"><button class="btn primary" data-action="copy-link">Copy link</button><a class="btn" href="/v/${c.id}" target="_blank" rel="noopener">Open viewer</a></div><button class="btn danger full" style="margin-top:16px" data-action="revoke">Stop sharing</button>`:!c.blob?'<p class="small muted">The shared link is inactive. Import your original video separately to create a new recording.</p>':`<div class="field"><label for="link-days">Link expires after</label><select id="link-days" ${shareLocked?'disabled':''}>${[1,3,7].map(d=>`<option value="${d}" ${(c.linkDays||7)===d?'selected':''}>${d} day${d===1?'':'s'}</option>`).join('')}</select></div><details class="password-options" ${c.passwordProtected?'open':''}><summary>${c.passwordProtected?'Sharing password required':'Add a password (optional)'}</summary><div class="field"><label for="share-password">${c.passwordProtected?'Sharing password (required for this protected video)':'Sharing password (optional)'}</label><input id="share-password" type="password" autocomplete="new-password" minlength="8" maxlength="128"><small>${shareLocked?'For a retry, use the original password. To change protection, delete this upload first.':'Use 8–128 characters. Send it separately from the link.'}</small></div></details><button class="btn primary full" data-action="publish" ${!health||!c.blob||sharingProblem(c)?'disabled':''}>${icon('arrow')}Publish & get a link</button>`}${cloud?'<button class="btn full" style="margin-top:10px" data-action="refresh-share">Refresh shared status</button><button class="btn danger full" style="margin-top:10px" data-action="delete-cloud">Delete uploaded video</button>':''}${sharingProblem(c)?`<div class="notice share-problem" role="status">${esc(sharingProblem(c))}${c.blob&&c.duration<=MAX_SECONDS?'<button class="btn" data-action="compress">Make a smaller copy</button>':''}</div>`:''}<progress id="upload-meter" value="0" max="100" aria-label="Upload progress" hidden></progress><div id="upload-progress" class="small muted" role="status">${c.uploadPaused?'Upload paused. Publish again to resume saved parts.':''}</div><button class="btn full" id="cancel-upload" data-action="cancel-upload" hidden>Pause upload</button><button class="btn full" data-action="check-sharing" ${health?'hidden':''} ${healthChecking?'disabled':''}>Retry sharing connection</button><p id="sharing-status">${!health?(healthChecked?(sharingIssue||'Sharing is unavailable here. Local import, trim and download remain available.'):'Checking sharing availability. Local import, trim and download remain available.'):''}</p></section><div class="notice">${formatTime(c.duration)} · ${((c.blob?.size||c.size||0)/1e6).toFixed(1)} MB<br>${!c.blob?'Recovery keys restored. Your original video is not included.':c.sample?'This is a sample clip, saved separately in your library.':'Stored on this device. Download a copy before clearing browser data.'}</div><section class="panel review-status-panel"><label for="review-status">Review status</label><select id="review-status">${['needs-feedback','changes-requested','approved'].map(v=>`<option value="${v}" ${(c.reviewStatus||'needs-feedback')===v?'selected':''}>${reviewLabel(v)}</option>`).join('')}</select><p id="review-status-message" class="small" role="status"></p></section><details class="notice recovery-note"><summary>Backup & device access</summary><p>This browser manages your shared link. <button class="btn" data-action="recovery">Back up recovery keys</button> Keep those keys private.</p></details></aside><section class="editor-tools" aria-label="Optional editing tools">${c.blob?`<details class="panel trim-panel"><summary>Trim video</summary><p>Trim a new copy on this device. Processing runs at playback speed; keep this tab open. The original stays intact.</p><div class="field-row"><div class="field"><label for="trim-start">Start (seconds)</label><input id="trim-start" type="number" min="0" step="0.1" value="0"></div><div class="field"><label for="trim-end">End (seconds)</label><input id="trim-end" type="number" min="0.25" max="${c.duration}" step="0.1" value="${c.duration.toFixed(1)}"></div></div><button class="btn" data-action="trim">Save trimmed copy</button><div id="trim-progress" class="small muted" role="status"></div></details>`:''}${extrasPanel(c)}${c.sample?'<section class="panel sample-feedback"><div class="eyebrow">EXAMPLE FEEDBACK</div><h2>One moment. A useful conversation.</h2><p>Illustrative comments for this walkthrough.</p><button class="timestamp" data-sample-time="5">0:05</button><p><strong>Alex</strong> · Could the checkout button be clearer?</p><blockquote><strong>Sam</strong> · Yes — increase the contrast and keep the label short.</blockquote><button class="timestamp" data-sample-time="10">0:10</button><p><strong>Alex</strong> · That works. Ready for another review.</p></section>':''}${c.blob?markupEditor():''}</section></div>`,'Recording','recording:'+c.id);fitPlayer($('#player'));$('#review-status').onchange=()=>run(async()=>{const field=$('#review-status'),next=field.value,old=c.reviewStatus||'needs-feedback';field.disabled=true;try{if((c.shared||c.uploadAttempted)&&!c.cloudDeleted&&!c.cloudMissing)await api('review-status',{id:c.id,owner:c.owner,reviewStatus:next});c.reviewStatus=next;await db.put(c);clips=await db.all();$('#review-status-message').textContent='Status saved.'}catch(e){field.value=old;throw e}finally{field.disabled=false}});mountExtras(c,{save:async extras=>{busy=true;try{if(c.shared&&!c.cloudDeleted)await api('details',{id:c.id,owner:c.owner,...extras});Object.assign(c,extras);await db.put(c);clips=await db.all()}finally{busy=false}},download:saveFile,error});if(c.blob)mountMarkupEditor(c);for(const b of document.querySelectorAll('[data-sample-time]'))b.onclick=()=>{$('#player').currentTime=Number(b.dataset.sampleTime);$('#player').play().catch(()=>{})};}
