function privacy(){if(recording||busy)return;shell(`<div class="privacy"><div class="eyebrow">CLEAR BY DEFAULT</div><h1>Your screen.<br>Your call.</h1><p class="muted">ScreenNote only uploads a video when you choose Publish. Recording and trimming happen in your browser.</p><section class="panel"><h2>Before you publish</h2><p>Recordings and recovery chunks are stored in this browser. Download videos you want to keep. Clearing site data, private browsing or losing this device can remove your local library.</p><h2>After you publish</h2><p>Older links from the previous storage service may be unavailable. Their videos have not been copied while that service denies access. If you have the original local video, refresh its shared status and publish a replacement link. Keep your original recovery keys.</p><p>The whole reviewed video is uploaded to private Supabase storage. An unlisted link lets anyone who has it watch and reply without a ScreenNote account. Do not include passwords or information you do not want the recipient to see. Unlisted does not mean encrypted end to end.</p><p>Links expire after 1, 3 or 7 days, as chosen before publication. Optional sharing passwords are verified on the server; issued playback URLs are bearer links with a five-minute lifetime. Captions, chapters and bug-report text you save are shared with viewers. Stop sharing blocks new viewer requests; already issued playback URLs may work for up to five more minutes. Expired uploads and abandoned reservations become eligible for deletion after a further 24 hours. ScreenNote reclaims them when new uploads reach shared capacity; cleanup is demand-driven, not a timed deletion guarantee.</p><h2>Small, honest first release</h2><p>Back up your recovery keys to restore management access after changing browsers or clearing site data. Keep them private: they authorize stopping sharing and deleting uploads. Videos are not included. <button class="btn" data-action="recovery">Recovery keys</button></p><p>Clips are limited to ten minutes and 50 MB. Shared uploads use a 1 GB storage budget. Pending uploads reserve space for both chunks and the assembled video. Deleting an uploaded video frees its slot after cleanup succeeds. Old expired uploads are also reclaimed when capacity is full. Local recording and downloads remain usable when sharing is full. Hosting quotas may pause online sharing; no paid upgrade is enabled by this application.</p><p>Screen capture needs a supported desktop browser. On phones or browsers without screen capture, record with your device and import MP4 or WebM. Camera, microphone and shared-screen audio require your browser’s permissions. Online sharing uses Supabase private file storage and a database for recording details and feedback. The app is hosted on Vercel. No AI analysis, advertising trackers or per-viewer charges are built in.</p><h2>Replies and reactions</h2><p>Replies are visible to everyone with the link. Names are self-entered, not verified identities. You can reply to any comment or reply. New replies reopen resolved threads. Comment authors can edit or remove their comments from the browser that posted them; the video creator can also remove comments and resolve threads. Clearing site data loses anonymous comment controls. Unsent drafts are kept in this tab’s session storage. Optional bubbles preview comments in the inline player; native fullscreen and picture in picture show the video only. Each clip supports 100 total comments and replies, including removed entries. Reactions use an anonymous browser identifier and are not verified unique-person counts.</p></section></div>`,'Privacy')}
function recovery(){if(recording||busy)return;shell(`<div class="privacy"><div class="eyebrow">KEEP CONTROL</div><h1>Take your keys with you.</h1><p class="muted">A private recovery file restores the ability to stop sharing or delete your uploaded videos from another browser at this same ScreenNote address.</p><section class="panel"><h2>Back up management access</h2><p>Keep this file private. Anyone with its keys can manage the uploads. It contains no video files: download videos separately.</p><button class="btn primary" data-action="backup-keys">Download recovery file</button></section><section class="panel" style="margin-top:24px"><h2>Restore your keys</h2><p>Choose a recovery file, or paste its complete JSON below. Keys are checked with the sharing service before saving. Existing local videos remain intact.</p><div class="field"><label for="recovery-file">ScreenNote recovery file</label><input id="recovery-file" type="file" accept="application/json,.json"></div><div class="field"><label for="recovery-json">Recovery JSON</label><textarea id="recovery-json" spellcheck="false" autocomplete="off" placeholder="Paste your ScreenNote recovery file here"></textarea></div><label class="consent"><input type="checkbox" id="restore-videos"> Also save active shared videos on this device (uses data and device storage)</label><button class="btn primary" data-action="restore-keys">Restore management access</button><p id="recovery-progress" class="small muted" role="status"></p></section></div>`,'Recovery');$('#recovery-file').onchange=e=>run(async()=>{const file=e.target.files[0];if(!file)return;if(file.size>524288)throw Error('Choose a recovery file smaller than 512 KB.');$('#recovery-json').value=await file.text()})}
async function restoreKeys(){const keys=recoveryKeys($('#recovery-json').value,location.origin);busy=true;const button=$('[data-action=restore-keys]');button.disabled=true;let restored=0,failed=0,videoFailed=0;try{for(const key of keys){$('#recovery-progress').textContent=`Checking key ${restored+failed+1} of ${keys.length}…`;try{const state=await api('manage',key),current=clips.find(c=>c.id===key.id);if(current&&current.owner!==key.owner)throw Error('This recording belongs to another key.');const record={...current,...state,...key,shared:state.status==='published',revoked:['revoked','expired','deleted'].includes(state.status),uploadAttempted:true,cloudDeleted:state.cleanupComplete,managementOnly:!current?.blob};await db.put(record);clips=await db.all();if($('#restore-videos').checked&&state.status==='published'&&state.expiresAt>Date.now()&&!record.blob){try{const response=await fetch(await api('restore-media',key).then(v=>v.mediaUrl));if(!response.ok)throw Error('Video download failed.');const file=new File([await response.blob()],record.title+'.'+(record.type==='video/mp4'?'mp4':'webm'),{type:record.type});const media=await importMedia(file),info=await metadata(media.blob);record.blob=media.blob;Object.assign(record,info,{managementOnly:false})}catch{videoFailed++}}await db.put(record);clips=await db.all();restored++}catch{failed++}}$('#recovery-json').value='';$('#recovery-file').value='';$('#recovery-progress').textContent=`Restored ${restored} recording${restored===1?'':'s'}.${failed?' '+failed+' key(s) could not be verified. Keep your file and retry when sharing is available.':''} ${videoFailed?' '+videoFailed+' video download(s) could not finish; management keys were restored. Keep the recovery file to retry.':''} Open My recordings to manage them.`}finally{busy=false;button.disabled=false}}
function dialog(title,body,save,label='Save'){
 const opener=document.activeElement;modal.onclose=()=>{const target=opener?.isConnected?opener:$('#main');target?.focus({preventScroll:true})};
 let saving=false;
 modal.innerHTML=`<form id="dialog-form"><h2 id="dialog-title">${title}</h2><div id="dialog-error" class="error-box" role="alert"></div>${body}<div class="dialog-actions"><button type="button" class="btn" id="cancel-dialog">Cancel</button><button class="btn primary" type="submit">${label}</button></div></form>`;
 modal.oncancel=e=>{if(saving)e.preventDefault()};
 $('#cancel-dialog').onclick=()=>{if(!saving)modal.close()};
 $('#dialog-form').onsubmit=async e=>{
  e.preventDefault();if(saving)return;$('#dialog-error').textContent='';
  const data=new FormData(e.target),controls=[...e.target.querySelectorAll('button,input,textarea')].map(node=>({node,disabled:node.disabled}));
  saving=true;busy=true;for(const {node} of controls)node.disabled=true;
  try{await save(data);modal.close()}catch(err){$('#dialog-error').textContent=err.message}
  finally{saving=false;busy=false;for(const {node,disabled} of controls)node.disabled=disabled}
 };modal.showModal();
}
