app.addEventListener('click',e=>{const b=e.target.closest('[data-action],[data-open],[data-rename]');if(!b||b.disabled||busy&&!['cancel-capture','cancel-upload'].includes(b.dataset.action))return;if((b.dataset.open||['home','help','privacy','recovery','refresh-share'].includes(b.dataset.action))&&!confirmEditorLeave())return;if(b.dataset.rename){const c=clips.find(c=>c.id===b.dataset.rename);dialog('Rename recording',`<div class="field"><label for="rename-title">Video title</label><input id="rename-title" name="title" maxlength="100" required value="${esc(c.title)}"></div>`,async f=>{const title=validTitle(f.get('title'));if((c.shared||c.uploadAttempted)&&!c.cloudDeleted&&!c.cloudMissing)await api('title',{id:c.id,owner:c.owner,title});c.title=title;await db.put(c);clips=await db.all();renderLibrary()});return}if(b.dataset.open){editor(clips.find(c=>c.id===b.dataset.open));return}run(()=>actions[b.dataset.action]?.())});
window.addEventListener('beforeunload',e=>{if(recording||busy||emergencyBlob||unsavedTitle()){e.preventDefault();e.returnValue=''}});
async function viewerPage(id){try{await db.open();const local=await db.get(id);viewerOwner=local?.owner||''}catch{viewerOwner=''}try{vote=localStorage.getItem('screennote-vote-'+id)||''}catch{}app.innerHTML=`<header class="viewer-top">${brand()}<a href="/" class="btn">Make your own video ${icon('arrow')}</a></header><main class="viewer" id="main" tabindex="-1"><div id="error" class="error-box" role="alert"></div><p class="muted">Opening your message…</p></main>`;try{viewData=await api('view',viewerPassword?{id,accessPassword:viewerPassword}:null,id);renderViewer()}catch(e){if(e.status===401){$('#main').innerHTML=`<h1>A password keeps this video private.</h1><p>${viewerPassword?'Password not accepted. ':''}Ask the sender for the sharing password.</p><form id="unlock-form" class="panel"><div id="error" class="error-box" role="alert"></div><div class="field"><label for="viewer-password">Sharing password</label><input id="viewer-password" type="password" maxlength="128" required autocomplete="current-password"></div><button class="btn primary">Open video</button></form>`;$('#unlock-form').onsubmit=e=>{e.preventDefault();viewerPassword=$('#viewer-password').value;run(()=>viewerPage(id))};return}$('#main').innerHTML=`<div id="error" class="error-box" role="alert">${esc(e.message)}</div><h1>This message is unavailable.</h1><p class="muted">The link may have expired, stopped sharing, or the hosting service may be unavailable.</p><a class="btn" href="/">Open ScreenNote</a>`}}
function renderViewer(){
 discussionUI?.destroy();const c=viewData;
 $('#main').innerHTML=`<div id="error" class="error-box" role="alert"></div><div class="eyebrow">A LITTLE CONTEXT FOR YOU</div><h1>${esc(isGeneratedTitle(c.title)?'Untitled recording':c.title)}</h1><p class="review-badge viewer-review" id="viewer-review" data-review="${esc(c.reviewStatus||'needs-feedback')}">${reviewLabel(c.reviewStatus)}</p><div class="viewer-grid"><div class="viewer-media"><div class="video-panel"><video id="viewer-player" src="${esc(c.mediaUrl)}" controls playsinline preload="metadata" aria-label="Shared video"></video></div><div class="player-tools"><label>Playback speed <select id="playback-speed" aria-label="Playback speed">${[.5,.75,1,1.25,1.5,2].map(n=>`<option value="${n}" ${n===1?'selected':''}>${n}×</option>`).join('')}</select></label>${document.pictureInPictureEnabled?'<button class="btn" id="picture-in-picture">Picture in picture</button>':''}</div><div class="reactions" aria-label="React to this video">${[['like','👍','Helpful'],['thanks','🙌','Thanks'],['idea','💡','Good idea']].map(([key,emoji,label])=>`<button class="btn" data-reaction="${key}" aria-pressed="${vote===key}">${emoji} ${label} <span>${c.reactions[key]}</span></button>`).join('')}</div><p class="small muted">${formatTime(c.end-c.start)} · Link expires ${new Date(c.expiresAt).toLocaleDateString()}<br>Anyone with this link can see replies. Guest names are not verified.</p><button class="btn" id="refresh-replies">Refresh conversation</button>${viewerContext(c)}</div><aside class="panel reply-panel">${discussionMarkup()}</aside></div>`;
 const p=$('#viewer-player');fitPlayer(p);mountViewerContext(c,p,saveFile);
 $('#playback-speed').onchange=e=>p.playbackRate=Number(e.target.value);
 if($('#picture-in-picture'))$('#picture-in-picture').onclick=()=>run(async()=>{if(document.pictureInPictureElement)await document.exitPictureInPicture();else await p.requestPictureInPicture()});
 p.onloadedmetadata=()=>p.currentTime=c.start;
 p.onplay=()=>{if(p.currentTime>=c.end-.05)p.currentTime=c.start};
 p.ontimeupdate=()=>{if(p.currentTime>c.end){p.pause();p.currentTime=c.end}};
 p.onerror=()=>error(Error('This video could not play here. Refresh the conversation to renew playback access, or try desktop Chrome or Safari.'));
 discussionUI=mountDiscussion({clip:c,player:p,panel:$('.reply-panel'),api,owner:viewerOwner,viewer,accessPassword:viewerPassword,update:next=>viewData=next,notify,error});
 $('#refresh-replies').onclick=()=>run(async()=>{
  const button=$('#refresh-replies');button.disabled=true;try{
   const next=await api('view',viewerPassword?{id:c.id,accessPassword:viewerPassword}:null,c.id);viewData=next;$('#viewer-review').textContent=reviewLabel(next.reviewStatus);$('#viewer-review').dataset.review=next.reviewStatus||'needs-feedback';
   $('#main h1').textContent=isGeneratedTitle(next.title)?'Untitled recording':next.title;
   const time=p.currentTime,playing=!p.paused;p.onloadedmetadata=()=>{p.currentTime=Math.max(c.start,Math.min(c.end,time));if(playing)p.play().catch(()=>{})};p.src=next.mediaUrl;
   discussionUI.update(next);for(const b of document.querySelectorAll('[data-reaction]'))b.querySelector('span').textContent=next.reactions[b.dataset.reaction];notify('Conversation and playback access refreshed. Your draft is kept.')
  }finally{button.disabled=false}
 });
 $('.reactions').onclick=e=>run(async()=>{const b=e.target.closest('[data-reaction]');if(!b||document.querySelector('.reactions button:disabled'))return;const buttons=[...document.querySelectorAll('[data-reaction]')];for(const button of buttons)button.disabled=true;const next=vote===b.dataset.reaction?'':b.dataset.reaction;try{const updated=await api('reaction',{id:c.id,accessPassword:viewerPassword,viewer,reaction:next});vote=next;try{localStorage.setItem('screennote-vote-'+c.id,vote)}catch{}viewData={...viewData,...updated};discussionUI.update(viewData);for(const button of buttons){button.setAttribute('aria-pressed',String(button.dataset.reaction===vote));button.querySelector('span').textContent=updated.reactions[button.dataset.reaction]}}finally{for(const button of buttons)button.disabled=false}})
}
async function listMicrophones(){if(!navigator.mediaDevices?.enumerateDevices)throw Error('This browser chooses the microphone in its permission prompt.');const devices=await navigator.mediaDevices.enumerateDevices(),mics=devices.filter(d=>d.kind==='audioinput'&&d.deviceId);const select=$('#mic-source');select.innerHTML='<option value="">Browser default</option>'+mics.map((d,i)=>`<option value="${esc(d.deviceId)}">${esc(d.label||'Microphone '+(i+1))}</option>`).join('');notify(mics.length?'Choose your microphone source. Labels may appear only after permission is granted.':'No named inputs are available yet. Browser default will use its permission chooser.')}
function markupEditor(){return `<details class="panel canvas-editor"><summary>Annotate or hide sensitive areas</summary><p>Create a new video with marks burned into every frame. Your original stays unchanged and must not be shared if it contains secrets. Pause the preview, then draw fixed masks or marks. Check the new copy before publishing.</p><div class="capture-frame"><video id="markup-video" controls muted playsinline aria-label="Annotation preview"></video><canvas id="markup-canvas" aria-label="Draw annotations on video"></canvas></div>${markupTools()}<div class="actions"><button class="btn" id="markup-toggle">Play / pause annotation preview</button><button class="btn" id="choose-thumbnail">Use preview frame as thumbnail</button></div><button class="btn primary" id="save-marked">Save marked copy</button><p id="marked-progress" role="status"></p></details>`}
function mountMarkupEditor(c){const video=$('#markup-video');video.src=objectURL;fitCaptureFrame(video);const items=[];mountTools(items);$('#markup-toggle').onclick=()=>video.paused?video.play().catch(error):video.pause();$('#choose-thumbnail').onclick=()=>run(async()=>{if(video.readyState<2)throw Error('Wait for the video preview to load.');const canvas=document.createElement('canvas');canvas.width=480;canvas.height=Math.round(480*video.videoHeight/video.videoWidth);canvas.getContext('2d').drawImage(video,0,0,canvas.width,canvas.height);c.thumbnail=canvas.toDataURL('image/jpeg',.7);await db.put(c);clips=await db.all();notify('Library thumbnail updated on this device.')});$('#save-marked').onclick=()=>run(async()=>{if(!items.length)throw Error('Draw at least one mark on the preview.');busy=true;$('#save-marked').disabled=true;try{const blob=await fixed(await trimVideo(c.blob,0,c.duration,p=>$('#marked-progress').textContent=`Saving marked copy · ${Math.round(p*100)}%`,structuredClone(items)),c.duration),info=await metadata(blob,c.duration),copy={id:randomId(),owner:secret(),title:c.title.slice(0,80)+' · marked',...trimExtras(c,0,c.duration),blob,type:blob.type.split(';')[0],createdAt:Date.now(),...info};await db.put(copy);clips=await db.all();busy=false;editor(copy);notify('Marked copy saved. Review it before publishing. The original is still in your library.')}finally{busy=false;const b=$('#save-marked');if(b)b.disabled=false}})}
function help(){if(recording||busy)return;shell(`<div class="privacy"><div class="eyebrow">A CLEAR FIRST MESSAGE</div><h1>Show the problem.<br>Share the moment.</h1><p>Record or import a short video, review your local copy, then publish when ready. Viewers need no account. ScreenNote is a limited free beta; no payment or subscription is enabled.</p><div class="help-grid"><section class="panel"><h2>Record with confidence</h2><ol><li>Use a desktop browser with screen capture, or import a device recording on mobile.</li><li>Choose microphone, camera and screen audio, then choose the source in your browser.</li><li>Add fixed masks and marks in setup. Begin starts a three-second countdown.</li><li>Stop and review the whole video, especially any sensitive areas. Download a backup.</li><li>Add optional captions, chapters or a bug report. Publish explicitly.</li></ol><p>ScreenNote cannot silently capture a screen. Permission is required each session. If your source or audio is unavailable, choose another source or import a video.</p></section><section class="panel"><button class="btn" data-action="recovery">Backup & device access</button><h2>Keyboard & playback</h2><p>While recording: Alt+Shift+P pauses/resumes; Alt+Shift+S stops. In a video view: K plays/pauses, J/L seek five seconds, M toggles mute. Shortcuts do not run while typing in a field.</p><p>Native video controls provide fullscreen and captions. The viewer also has playback speed and picture in picture when the browser supports it.</p><h2>Private by choice</h2><p>Anyone with an unlisted link can view it unless you set a sharing password. Send that password separately. Playback links already issued can work for up to five minutes after revocation. Export management keys and download videos separately.</p></section><section class="panel"><h2>Recording & sharing limits</h2><p>Local recording and import: up to 30 minutes / 250 MB. Shared video: up to 10 minutes / 50 MB. Shared storage has a 1 GB budget across the app; smaller videos leave room for more recordings. Links expire after 1, 3 or 7 days. Capacity or hosting quotas can pause sharing; local tools remain available.</p><p>Captions are supplied by you in SRT/WebVTT format. No paid transcription service, AI analysis or advertising tracker runs here. Browser storage can be lost; keep downloads.</p><button class="btn" data-action="privacy">Read privacy & retention</button></section><section class="panel"><h2>Help validate this beta</h2><p>Try a short, non-sensitive recording. Check playback, audio, captions and feedback with your recipient. Download a local test report to share through your own channel. No personal information is required, and feedback is not sent automatically.</p><button class="btn primary" data-action="beta-feedback">Create a test report</button><p>Real Android, iOS, Safari, tablet and native permission testing remains a release gate. This app does not promise universal browser support.</p></section></div></div>`,'Help')}
actions['beta-feedback']=()=>dialog('Report your test',`<p>Save this report locally. Nothing is sent automatically.</p><div class="field"><label for="test-device">Browser / device</label><input id="test-device" name="device" maxlength="200" required></div><div class="field"><label for="test-task">Task tested</label><input id="test-task" name="task" maxlength="300" required></div><div class="field"><label for="test-result">What happened?</label><textarea id="test-result" name="result" maxlength="2000" required></textarea></div>`,async f=>saveFile(new Blob([JSON.stringify({version:APP_VERSION,device:f.get('device'),task:f.get('task'),result:f.get('result')},null,2)],{type:'application/json'}),'screennote-beta-test.json'),'Download test report');
document.addEventListener('keydown',e=>{if(e.target.closest('input,textarea,select,[contenteditable=true]')||modal.open)return;if(busy)return;if(e.altKey&&e.shiftKey){if(capture?.begun&&recording&&e.code==='KeyP'){e.preventDefault();actions.pause()}if(capture?.begun&&recording&&e.code==='KeyS'){e.preventDefault();actions.stop()}return}if(e.ctrlKey||e.metaKey||e.altKey)return;const p=$('#viewer-player')||$('#player');if(!p)return;if(e.code==='KeyK'){e.preventDefault();p.paused?p.play().catch(()=>{}):p.pause()}else if(e.code==='KeyJ'||e.code==='KeyL'){e.preventDefault();p.currentTime=Math.min(p.duration||0,Math.max(0,p.currentTime+(e.code==='KeyJ'?-5:5)))}else if(e.code==='KeyM'){e.preventDefault();p.muted=!p.muted}});

async function boot(){const match=location.pathname.match(/^\/v\/([a-f0-9-]{36})$/);if(match||location.pathname.startsWith('/v/')){await viewerPage(match?.[1]||location.pathname.slice(3));return}try{await db.open();libraryReady=true;clips=await db.all();home();checkSharing();const drafts=await db.all('drafts');if(drafts.some(d=>d.chunks.length)){dialog('A recording was interrupted',`<p>ScreenNote found saved recording chunks on this device. Recover the most recent partial recording? Some browsers may not be able to play an interrupted file.</p>`,async()=>{const d=drafts.filter(d=>d.chunks.length).sort((a,b)=>b.createdAt-a.createdAt)[0],blob=await fixed(new Blob(d.chunks,{type:d.chunks[0].type}),d.seconds);const info=await metadata(blob,d.seconds),c={id:randomId(),owner:secret(),title:'Recovered recording',blob,type:blob.type.split(';')[0],createdAt:Date.now(),...info};await db.finish(c,d.id);clips=await db.all();editor(c)},'Recover recording')}}catch(e){app.innerHTML=`<main class="content" id="main" tabindex="-1"><h1>We couldn’t open your local library.</h1><p class="error-box">${esc(e.message)}</p><p>Use a regular browser with device storage enabled. Do not clear site data if you have recordings saved here.</p></main>`}}
boot().then(async()=>{if(!globalThis.AppHost)return;const id=new URLSearchParams(location.search).get('nativeRecording');if(!/^[a-f0-9-]{36}$/.test(id||''))return;try{const response=await fetch('/__native_recordings/'+id);if(!response.ok)throw Error('This native recording is unavailable. Open Recordings to choose it again.');const blob=await response.blob();await importVideo(new File([blob],'Screen recording.mp4',{type:'video/mp4'}));history.replaceState(null,'','/')}catch(e){error(e)}});

if(globalThis.AppHost)window.handleAndroidBack=()=>{if(busy||recording)return true;if(modal.open){modal.close();return true}if(selected){if(confirmEditorLeave())home();return true}return false};

if(globalThis.AppHost)window.requestAndroidHome=()=>{if(!busy&&!recording&&confirmEditorLeave())home();return true};

if(globalThis.AppHost)window.confirmAndroidRecordingImport=()=>{if(busy||recording||emergencyBlob){notify("Finish the current operation and save any recovered video before importing a recording.");return false}return confirmEditorLeave()};
